import {MARKETS,PRODUCTS,EXAMPLES} from './data.mjs';
import {money,localPrice,compareProducts,addCart,checkoutDraft} from './engine.mjs';
import {runShoppingTurn} from './agent.mjs';
import {productArt} from './art.mjs';
import {initialLab,renderStrategyPage,exportStrategy} from './strategy-ui.mjs';
import {DEFAULT_WEIGHTS,STRATEGIES} from './search.mjs';
import {EVAL_CASES} from './eval-data.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
function conversation(market='US'){return{id:uid(),title:'新对话',market,context:{},messages:[]};}
let stored;try{stored=JSON.parse(localStorage.getItem('shopmate-v2'));}catch{}
let state=stored?.version===2&&Array.isArray(stored.sessions)?stored:{version:2,sessions:[conversation()],currentId:null,cart:[],compare:[],events:[],language:'zh'};
if(!state.currentId||!state.sessions.some(x=>x.id===state.currentId))state.currentId=state.sessions[0].id;
state.strategy=STRATEGIES[state.strategy]?state.strategy:'match';state.searchWeights=state.searchWeights||{...DEFAULT_WEIGHTS};
let ui={lab:initialLab(),productOrigin:null,detailOpen:null,view:['assistant','catalog','compare','cart','checkout','guide','strategy'].includes(location.hash.slice(1))?location.hash.slice(1):'assistant',query:'',category:'all',search:'',price:'',sort:'match',busy:false,provider:'rules',handoff:false};let toastTimer;
const session=()=>state.sessions.find(x=>x.id===state.currentId),market=()=>session().market,L=(zh,en)=>state.language==='en'?en:zh;
const cat=k=>({audio:L('耳机与音频','Audio'),camera:L('相机与影像','Cameras'),charger:L('充电与数码','Charging'),bag:L('包袋与出行','Bags'),home:L('家居与灯具','Home')}[k]||L('未指定','Not specified'));
const concern=k=>({noise:L('降噪','Noise cancellation'),travel:L('旅行','Travel'),battery:L('续航','Battery'),waterproof:L('防水','Waterproof'),gift:L('送礼','Gift'),fast:L('快充','Fast charging'),portable:L('便携','Portable')}[k]||k);
const paths={spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',arrow:'M4 12h16 m-6-6 6 6-6 6',cart:'M3 3h2l3 12h10l3-9H6 M10 21h.01 M18 21h.01',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',plus:'M12 5v14 M5 12h14',compare:'M5 3v18 M19 3v18 M2 7h6 M16 17h6 M9 12h6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3a17 17 0 0 1 0 18 17 17 0 0 1 0-18',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',shield:'m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7l9-4Z m-4 9 3 3 5-5',bag:'M5 7h14l2 14H3L5 7Z M8 7V5a4 4 0 0 1 8 0v2',download:'M12 3v12 m-4-4 4 4 4-4 M4 16v5h16v-5',back:'M20 12H4 m6-6-6 6 6 6'};
const ic=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
function save(){localStorage.setItem('shopmate-v2',JSON.stringify(state));}
function event(type,detail){state.events.unshift({id:uid(),time:new Date().toISOString(),type,detail});state.events=state.events.slice(0,1000);save();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function nav(view){ui.view=view;history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
function cartItems(){return state.cart.filter(x=>x.market===market());}
function cartCount(){return cartItems().reduce((n,x)=>n+x.quantity,0);}
function header(){return `<header class="header"><div class="header-inner"><a href="#assistant" class="brand" data-nav="assistant"><span class="brand-icon">s<span>✦</span></span><span>ShopMate<small>YOUR SHOPPING COPILOT</small></span></a><nav aria-label="主要导航">${[['assistant','购物助手','Shopping assistant'],['catalog','探索商品','Explore'],['compare','商品对比','Compare'],['strategy','搜索策略','Strategy']].map(([k,zh,en])=>`<button class="nav-item ${ui.view===k?'active':''}" data-nav="${k}">${L(zh,en)}${k==='compare'&&state.compare.length?`<b>${state.compare.length}</b>`:''}</button>`).join('')}</nav><div class="header-actions"><select id="market" aria-label="购物市场">${Object.entries(MARKETS).map(([k,m])=>`<option value="${k}" ${market()===k?'selected':''}>${m.flag} ${k} · ${m.currency}</option>`).join('')}</select><button class="icon-button language" data-action="language" aria-label="切换语言">${state.language==='zh'?'EN':'中'}</button><button class="cart-button ${ui.view==='cart'?'active':''}" data-nav="cart" aria-label="购物车">${ic('cart')}<span>${cartCount()}</span></button></div></div></header>`;}
function footer(){return `<footer><div><span class="small-brand">ShopMate</span> ${L('帮你选得更合适。','Find what fits you.')}</div><div><span class="demo-dot"></span>${L('演示店铺 · 模拟商品与固定汇率','Demo store · Synthetic products and illustrative rates')}<button data-nav="guide">${L('项目说明','About this project')} ↗</button></div></footer>`;}
function head(eyebrow,title,sub,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="button-row">${buttons}</div></div>`;}
function composer(welcome=false){return `<form id="chat-form" class="composer ${welcome?'welcome-composer':''}"><label class="sr-only" for="shopping-query">购物需求</label><textarea id="shopping-query" maxlength="2000" required placeholder="${L('告诉我你的预算、用途和在意的地方…','Tell me your budget, plans, and what matters to you…')}" ${ui.busy?'disabled':''}>${esc(ui.query)}</textarea><div class="composer-bottom"><span>${ic('globe')} ${MARKETS[market()].en} <i>·</i> ${L('可以接着追问','Follow-up questions welcome')}</span><button class="send" type="submit" aria-label="发送购物需求" ${ui.busy?'disabled':''}>${ui.busy?'…':ic('arrow')}</button></div></form>`;}
function productCard(p,{marketCode=market(),reason=false}={}){const included=state.compare.includes(p.id);return `<article class="product-card" data-product-id="${p.id}"><button class="art-button" data-product="${p.id}" aria-label="查看 ${esc(p.name)} 详情">${productArt(p)}</button>${p.stock===0?`<span class="stock-badge">${L('暂时缺货','Sold out')}</span>`:reason&&p.score?`<span class="match-badge">${Number(p.score).toFixed(1)} ${L('策略分','rule score')}</span>`:''}<div class="product-body"><div class="product-category">${cat(p.category)}<span>★ ${p.rating}</span></div><button class="product-name" data-product="${p.id}">${esc(p.name)}</button><p>${esc(p.description)}</p><div class="price-row"><strong>${money(localPrice(p,marketCode),marketCode)}</strong><span>${L('约','Est.')} ${p.days[marketCode]} ${L('天','days')}</span></div><div class="product-actions"><button class="btn primary" data-choose-variant="${p.id}" ${!p.stock?'disabled':''}>${ic('plus')}${L('加入购物车','Add to cart')}</button><button class="btn square ${included?'selected':''}" data-compare="${p.id}" aria-label="${included?'移除':'加入'}对比 ${esc(p.name)}" title="${L('加入对比','Compare')}">${ic(included?'check':'compare')}</button></div></div></article>`;}
function comparisonTable(items,m){const rows=[['价格','Price',p=>money(localPrice(p,m),m)],['续航标称','Rated battery',p=>p.specs.battery?p.specs.battery+'h':L('未提供','Not provided')],['重量','Weight',p=>p.specs.weight?p.specs.weight+'g':L('未提供','Not provided')],['降噪','ANC',p=>p.tags.includes('noise')?L('支持','Yes'):L('未标注','Not listed')],['容量','Capacity',p=>p.specs.capacity?p.specs.capacity+'mAh':'—'],['充电 / 输出功率','Power',p=>p.specs.powerW?p.specs.powerW+'W':'—'],['包袋容量','Bag volume',p=>p.specs.volumeL?p.specs.volumeL+'L':'—'],['视频规格','Video',p=>p.specs.video||'—'],['亮度','Brightness',p=>p.specs.brightnessLm?p.specs.brightnessLm+'lm':'—'],['商品评分','Rating',p=>'★ '+p.rating],['演示配送','Demo delivery',p=>p.days[m]+L('天',' days')],['库存','Stock',p=>p.stock?L('有货','In stock'):L('缺货','Sold out')],['退换与保修','Returns / warranty',p=>p.policy]];return `<div class="comparison-scroll"><table class="comparison"><thead><tr><th>${L('比较维度','Features')}</th>${items.map(p=>`<th><button data-product="${p.id}">${esc(p.name)}</button></th>`).join('')}</tr></thead><tbody>${rows.map(([zh,en,fn])=>`<tr><th>${L(zh,en)}</th>${items.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th></th>${items.map(p=>`<td><button class="btn small primary" data-choose-variant="${p.id}" ${!p.stock?'disabled':''}>${L('选这款','Choose this')}</button></td>`).join('')}</tr></tbody></table></div><p class="table-note">${L('参数来自演示商品池。耳塞续航包含充电盒；不同品类并非同条件实测。配送和费用需店铺确认。','Specs come from the demo catalog. Earbud battery includes the case; cross-category values are not controlled tests. Confirm delivery with the store.')}</p>`;}
function welcome(){return `<section class="welcome"><div class="welcome-label"><span class="demo-dot"></span> A LITTLE HELP. A BETTER CHOICE.</div><h1>${L('你说需求，<br><em>我帮你挑选。</em>','Your needs.<br><em>Your perfect match.</em>')}</h1><p>${L('从预算到偏好，一起找到真正适合你的商品。','From budget to preferences, find something that’s right for you.')}</p><div class="welcome-input">${composer(true)}<div class="examples">${EXAMPLES.map((x,i)=>`<button data-example="${i}">${ic(['spark','bag','search','globe'][i])}${esc(L(x.zh,x.en))}</button>`).join('')}</div></div><div class="trust-row"><span>${ic('shield')}${L('预算与库存检查','Budget & stock checks')}</span><span>${ic('compare')}${L('有依据的商品对比','Evidence-based comparisons')}</span><span>${ic('message')}${L('保留上下文，继续追问','Follow-ups with context')}</span></div></section><section class="discovery"><div class="section-heading"><div><div class="eyebrow">A FEW THINGS YOU MIGHT LIKE</div><h2>${L('先从这些好物开始','A few good places to start')}</h2></div><button class="text-button" data-nav="catalog">${L('探索全部商品','Explore all products')}${ic('arrow')}</button></div><div class="product-grid featured">${['p1','p9','p2','p3'].map(id=>productCard(PRODUCTS.find(p=>p.id===id))).join('')}</div></section>`;}
function message(msg,index){if(msg.role==='user')return `<div class="user-message"><div>${esc(msg.text)}</div><span>YOU</span></div>`;const r=msg.result;return `<article class="assistant-message" ${r.search?`data-search-id="${msg.id}" data-search-market="${msg.market}" data-search-strategy="${msg.strategy||'match'}"`:""}><div class="assistant-label"><span class="assistant-symbol">✦</span> ShopMate <small>${L('购物助手','Shopping assistant')}</small></div><div class="reply">${esc(r.reply)}</div>${r.kind==='comparison'&&r.products.length?comparisonTable(r.products,msg.market):r.products.length?`<div class="product-grid response-products">${r.products.map(p=>productCard(p,{marketCode:msg.market,reason:r.kind==='recommendation'})).join('')}</div>`:''}${r.kind==='cart_action'&&r.action?.type==='choose_variant'?`<div class="reply-note">${L('点击商品上的“加入购物车”选择颜色；确认后才加入。','Use “Add to cart” on the product card to choose a color.')}</div>`:''}${r.checks?.length&&r.products.length?`<div class="checks">${r.checks.map(c=>`<span>${ic(c.pass?'check':'close')}${esc(c.label)}</span>`).join('')}</div>`:''}<details class="tool-trace"><summary>${ic('spark')}${L('查看本次决策过程','View decision steps')} <span>${r.trace.length} ${L('步','steps')}</span></summary><div>${r.trace.map((x,i)=>`<div class="trace-line"><b>${i+1}</b><code>${esc(x.tool)}</code><p>${esc(x.detail)}</p></div>`).join('')}</div></details>${r.search?`<button class="btn small search-inspect" data-inspect-search="${msg.id}">${L('查看这次搜索策略','Inspect this search')} ↗</button>`:''}${index===session().messages.length-1&&r.products.length?`<div class="followups">${[r.products.length>=2?L('比较前两款','Compare the first two'):L('这款的退货政策是什么？','What is the return policy?'),L('哪款续航更长？','Which has the longest battery?'),L('便宜一点','Something cheaper'),L('把第一款加入购物车','Add the first one to my cart')].map(q=>`<button data-followup="${esc(q)}">${esc(q)} ↗</button>`).join('')}</div>`:''}</article>`;}
function preferences(){const q=session().context.query;return `<aside class="preferences"><div class="panel"><div class="side-heading">${ic('spark')}${L('你的购物偏好','Your shopping brief')}</div>${q?`<dl><dt>${L('购物市场','Market')}</dt><dd>${MARKETS[market()].flag} ${MARKETS[market()].en}</dd><dt>${L('预算上限','Budget')}</dt><dd>${q.budget!==null?esc(q.budget+' '+q.currency):L('未指定','Not specified')}</dd><dt>${L('商品品类','Category')}</dt><dd>${cat(q.category)}</dd><dt>${L('在意的地方','Priorities')}</dt><dd><div class="tags">${q.concerns.map(c=>`<span>${concern(c)}</span>`).join('')||L('可以继续告诉我','Tell me more')}</div></dd></dl>`:`<p>${L('告诉我你的预算与偏好，后续追问会保留这些条件。','Tell me your budget and preferences; I’ll keep them for follow-ups.')}</p>`}</div><div class="side-note">${L('还没找到合适的？试着调整预算、取消某个要求，或说“换成音箱”。','Not quite right? Adjust your budget, remove a requirement, or try another category.')}</div>${state.compare.length?`<div class="panel"><div class="side-heading">${ic('compare')}${L('待比较的商品','Your shortlist')}</div>${state.compare.map(id=>{const p=PRODUCTS.find(p=>p.id===id);return `<div class="shortlist"><span>${esc(p.name)}</span><button data-compare="${id}" aria-label="移除对比 ${esc(p.name)}">×</button></div>`;}).join('')}<button class="btn full" data-nav="compare">${L('打开对比','Compare products')}${ic('arrow')}</button></div>`:''}</aside>`;}
function assistantView(){const s=session();return !s.messages.length?welcome():`${head('YOUR SHOPPING CONVERSATION',L('一起选到更合适的。','Let’s find your fit.'),L('可以比较商品、调整预算，也可以继续询问规格和政策。','Compare, refine your budget, or ask about specs and policies.'),`<button class="btn" data-action="history">${ic('clock')}${L('历史对话','History')}</button><button class="btn" data-action="new-chat">${ic('plus')}${L('新对话','New chat')}</button>`)}<div class="chat-layout"><section class="chat-column"><div class="messages">${s.messages.map(message).join('')}</div><div class="chat-composer">${composer()}<p>${L('演示商品信息，仅供体验。','Demo product information for exploration.')}</p></div></section>${preferences()}</div>`;}
function catalogView(){let items=PRODUCTS.filter(p=>(ui.category==='all'||p.category===ui.category||p.kind===ui.category)&&`${p.name} ${p.zh}`.toLowerCase().includes(ui.search.toLowerCase())&&(!ui.price||localPrice(p,market())<=Number(ui.price)));items.sort(ui.sort==='price'?(a,b)=>a.price-b.price:ui.sort==='rating'?(a,b)=>b.rating-a.rating:(a,b)=>a.stock===0?1:b.stock===0?-1:0);return `${head('THE DEMO COLLECTION',L('探索你的下一件好物。','Find your next good thing.'),L('先逛逛，再让购物助手帮你比较与筛选。','Explore the collection, then ask your shopping assistant to narrow it down.'))}<div class="catalog-toolbar"><div class="category-tabs">${[['all','全部','All'],['headphones','头戴耳机','Headphones'],['earbuds','耳塞','Earbuds'],['speaker','音箱','Speakers'],['camera','相机','Cameras'],['charger','充电','Charging'],['bag','包袋','Bags'],['lamp','桌灯','Lamps']].map(([k,zh,en])=>`<button data-category="${k}" class="${ui.category===k?'active':''}">${L(zh,en)}</button>`).join('')}</div><div class="catalog-filters"><label class="search-field">${ic('search')}<input id="catalog-search" value="${esc(ui.search)}" placeholder="${L('搜索商品','Search products')}"></label><label class="budget-field"><span>≤ ${MARKETS[market()].symbol}</span><input type="number" min="0" id="catalog-budget" value="${esc(ui.price)}" placeholder="${L('预算','Budget')}"></label><select id="catalog-sort" aria-label="商品排序"><option value="match">${L('默认排序','Recommended')}</option><option value="price" ${ui.sort==='price'?'selected':''}>${L('价格从低到高','Price: low to high')}</option><option value="rating" ${ui.sort==='rating'?'selected':''}>${L('评分优先','Top rated')}</option></select></div></div><div class="catalog-count">${items.length} ${L('件商品','products')} · ${MARKETS[market()].currency}</div><div class="product-grid catalog-products">${items.map(p=>productCard(p)).join('')}</div>${!items.length?`<div class="empty">${L('没有符合筛选条件的商品。试着调整关键词或预算。','No products match these filters. Try a different search or budget.')}</div>`:''}`;}
function compareView(){const items=compareProducts(state.compare,market());return `${head('SIDE BY SIDE',L('把选择放在一起看。','Good choices, side by side.'),L('最多比较三款商品。先看差异，再决定哪款更适合自己。','Compare up to three products and decide what matters most.'),`<button class="btn" data-nav="catalog">${ic('plus')}${L('添加商品','Add products')}</button>`)}${items.length?`<div class="compare-products">${items.map(p=>`<div class="compare-picked">${productArt(p)}<div><strong>${esc(p.name)}</strong><span>${money(localPrice(p,market()),market())}</span></div><button data-compare="${p.id}" aria-label="移除对比 ${esc(p.name)}">×</button></div>`).join('')}</div><section class="panel compare-panel">${comparisonTable(items,market())}</section><button class="btn primary" data-action="ask-compare">${ic('spark')}${L('让助手帮我分析','Ask the assistant to compare')}</button>`:`<div class="empty panel">${ic('compare')}<h2>${L('先选两款，我们帮你比较。','Pick two and let’s compare.')}</h2><p>${L('在商品卡上点击对比图标，将商品加入这里。','Use the compare icon on any product card.')}</p><button class="btn primary" data-nav="catalog">${L('去选商品','Explore products')}${ic('arrow')}</button></div>`}`;}
function cartView(){const items=cartItems(),draft=checkoutDraft(state.cart,market());return `${head('YOUR BAG',L('你的购物车。','Your shopping bag.'),L('确认商品、颜色与数量，然后查看结账交接。','Review products, colors, and quantities before checkout.'),`<button class="btn" data-nav="catalog">${ic('back')}${L('继续选购','Keep shopping')}</button>`)}${!items.length?`<div class="empty panel">${ic('bag')}<h2>${L('购物车还是空的。','Your bag is empty.')}</h2><p>${L('告诉助手你的需求，或者先逛逛商品。','Tell the assistant what you need, or explore the collection.')}</p><button class="btn primary" data-nav="assistant">${L('帮我选一款','Help me choose')}${ic('spark')}</button></div>`:`<div class="cart-layout"><section class="panel cart-list">${items.map(x=>{const p=PRODUCTS.find(p=>p.id===x.productId),v=p.variants.find(v=>v.id===x.variantId);return `<article class="cart-row">${productArt(p)}<div class="cart-info"><strong>${esc(p.name)}</strong><small>${L('颜色','Color')} · ${esc(L(v.zh,v.name))}</small><span>${money(localPrice(p,market()),market())}</span><div class="quantity"><button data-quantity="${esc(x.id)}" data-delta="-1" aria-label="减少 ${esc(p.name)} 数量">−</button><b>${x.quantity}</b><button data-quantity="${esc(x.id)}" data-delta="1" aria-label="增加 ${esc(p.name)} 数量">+</button></div></div><div class="cart-row-right"><strong>${money(localPrice(p,market())*x.quantity,market())}</strong><button data-remove-cart="${esc(x.id)}">${L('移除','Remove')}</button></div></article>`;}).join('')}</section>${orderSummary(draft,false)}</div>`}`;}
function orderSummary(draft,checkout){return `<aside class="panel order-summary"><h2>${L('购物清单','Order summary')}</h2><div class="summary-line"><span>${L('市场','Market')}</span><strong>${MARKETS[market()].flag} ${market()}</strong></div><div class="summary-line"><span>${L('商品数量','Items')}</span><strong>${cartCount()}</strong></div><div class="summary-line"><span>${L('商品小计','Subtotal')}</span><strong>${draft.ok?money(draft.subtotal,market()):'—'}</strong></div><div class="summary-line"><span>${L('运费与税费','Shipping & tax')}</span><span>${L('店铺结账时确认','Confirmed by store')}</span></div><div class="order-total"><span>${L('商品合计','Items total')}</span><strong>${draft.ok?money(draft.subtotal,market()):'—'}</strong></div><button class="btn primary full" data-action="${checkout?'export-handoff':'checkout'}" ${!draft.ok?'disabled':''}>${checkout?ic('download'):ic('arrow')}${checkout?L('生成结账交接单','Create checkout handoff'):L('去结账（演示）','Checkout preview')}</button><p>${L('当前为演示店铺，不创建真实订单或收款。','This demo creates no real orders and collects no payment.')}</p></aside>`;}
function checkoutView(){const d=checkoutDraft(state.cart,market());return `${head('CHECKOUT HANDOFF',L('确认你的购物选择。','Review your choices.'),L('检查商品与规格，再交由真实店铺确认履约和支付。','Review your items; fulfillment and payment belong to the store.'),`<button class="btn" data-nav="cart">${ic('back')}${L('返回购物车','Back to bag')}</button>`)}${!d.ok?`<div class="empty panel"><h2>${L('请先检查购物车。','Please review your bag first.')}</h2><button class="btn primary" data-nav="cart">${L('打开购物车','Open bag')}</button></div>`:`<div class="checkout-steps"><span class="done">${ic('check')}${L('1 商品与规格','1 Items & options')}</span><span class="active">2 ${L('结账交接预览','Checkout handoff')}</span><span>3 ${L('真实店铺支付','Store payment')}</span></div><div class="cart-layout"><section class="panel checkout-content"><div class="side-heading">${ic('shield')}${L('商品与库存检查通过','Items and stock verified')}</div>${d.items.map(x=>`<div class="checkout-item"><div><strong>${esc(x.product)}</strong><small>${esc(x.variant)} · Qty ${x.quantity}</small></div><b>${money(x.unitPrice*x.quantity,market())}</b></div>`).join('')}<div class="handoff-note"><h3>${L('这里会交接给店铺。','The store takes it from here.')}</h3><p>${L('演示商品未连接真实店铺，因此不收集地址、银行卡或付款信息。你可以生成包含商品、颜色、数量、币种与小计的交接单；接入真实店铺后，这一步才跳转至店铺结账页。','These demo products are not connected to a live store. No address or payment details are collected. Export a handoff with product options, quantities, currency, and subtotal; a live store integration would provide the checkout destination.')}</p>${ui.handoff?`<span class="success">${ic('check')}${L('交接单已生成；尚未下单。','Handoff created; no order placed.')}</span>`:''}</div></section>${orderSummary(d,true)}</div>`}`;}
function guideView(){return `${head('ABOUT SHOPMATE',L('一个以选购为中心的导购助手。','A shopping assistant, built around you.'),L('从需求到推荐、比较与购物车，让购物决策更清楚。','From needs to recommendations, comparisons, and your shopping bag.'))}<div class="guide-layout"><section class="panel guide"><h2>${L('这次项目的正确主线','The shopping journey')}</h2><div class="journey">${[L('说出需求','Share needs'),L('理解偏好','Understand'),L('筛选推荐','Recommend'),L('比较追问','Compare & refine'),L('确认规格','Choose options'),L('购物车与结账交接','Bag & checkout')].map((x,i)=>`<span><b>0${i+1}</b>${x}</span>`).join('')}</div><h3>${L('你可以怎么试','Try a conversation')}</h3><ol><li>推荐100美元以内，适合坐飞机的降噪耳机。</li><li>比较前两款。</li><li>哪款续航更长？</li><li>便宜一点。</li><li>把第一款加入购物车。</li></ol><h3>${L('当前可以运行的功能','What works today')}</h3><p>${L('多语言购物需求、预算和特性过滤、可解释推荐、多轮偏好继承、商品参数对比、政策问答、颜色确认、购物车数量与结账交接单。','Multilingual shopping requests, budget and feature filtering, explainable recommendations, follow-up context, comparisons, policies, color selection, quantities, and checkout handoffs.')}</p><h3>${L('演示范围','Demo scope')}</h3><p>${L('商品、价格、库存、时效与政策为演示数据。固定汇率不代表实时汇率；续航不是同条件实测。默认规则编排，本地可配置模型辅助需求抽取。未接入真实Shopify、付款或履约系统。','Products, prices, stock, delivery and policies are demo data. Exchange rates are illustrative; battery figures are not controlled tests. Rules run by default, with optional local model extraction. No live store, payment, or fulfillment is connected.')}</p><div class="button-row"><button class="btn" data-action="download-guide">${ic('download')}${L('下载项目说明','Download project brief')}</button><button class="btn" data-action="export-events">${L('导出本轮事件','Export events')}</button></div></section><aside class="panel guide"><h3>${L('模型负责理解，程序负责核验','Understand, then verify')}</h3><p>${L('模型或规则抽取需求；实际商品筛选、排序、规格检查和购物车校验由程序执行。缺少颜色信息时先询问，不擅自确定商品规格。','Models or rules extract needs. Code filters, ranks, validates options, and checks the bag. Missing color choices are confirmed before adding items.')}</p><h3>${L('保存在哪里','Where it is saved')}</h3><p>${L('购物车和对话保存在当前浏览器，刷新后仍可继续；新对话会清空本次偏好，但保留购物车。','Conversations and your bag stay in this browser. A new conversation resets preferences and keeps your bag.')}</p><button class="btn full" data-action="history">${ic('clock')}${L('历史对话','Conversation history')}</button></aside></div>`;}
function render(){const views={assistant:assistantView,catalog:catalogView,compare:compareView,cart:cartView,checkout:checkoutView,guide:guideView,strategy:()=>renderStrategyPage(ui.lab,state.events,state.strategy,L)};$('#app').innerHTML=`${header()}<main>${(views[ui.view]||assistantView)()}</main>${footer()}${state.compare.length&&ui.view!=='compare'?`<div class="compare-dock"><span>${state.compare.length} ${L('款待对比','in your comparison')}</span><button data-nav="compare">${L('查看对比','Compare')}${ic('arrow')}</button></div>`:''}`;document.documentElement.lang=state.language==='zh'?'zh-CN':'en';observeSearchCards();}
function modal(title,body){$('#overlay').innerHTML=`<div class="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button data-action="close-modal" aria-label="关闭">${ic('close')}</button></div><div class="modal-body">${body}</div></section></div>`;$('#overlay').querySelector('select,input,button')?.focus();}
function closeModal(){if(ui.detailOpen){event('product_detail_closed',ui.detailOpen);ui.detailOpen=null;}$('#overlay').innerHTML='';}
function file(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function variantModal(id){const p=PRODUCTS.find(p=>p.id===id);if(!p)return;modal(L('确认颜色，再加入购物车','Choose a color'),`<div class="variant-product">${productArt(p)}<div><h3>${esc(p.name)}</h3><strong>${money(localPrice(p,market()),market())}</strong><small>${L('库存','Stock')}: ${p.stock}</small></div></div><form id="variant-form" data-product="${p.id}"><label for="variant">${L('颜色','Color')}</label><select id="variant" name="variant" required><option value="">${L('请选择颜色','Select a color')}</option>${p.variants.map(v=>`<option value="${v.id}">${esc(L(v.zh,v.name))}</option>`).join('')}</select><button class="btn primary full" type="submit" ${!p.stock?'disabled':''}>${ic('plus')}${L('确认加入购物车','Confirm add to cart')}</button></form>`);}
function add(productId,variantId){const r=addCart(state.cart,productId,variantId,market());if(!r.ok){toast(r.error==='stock_limit'?L('数量已达到库存上限。','Stock limit reached.'):L('请检查颜色、市场和库存。','Please check options and availability.'));return false;}state.cart=r.cart;const row=state.cart.find(x=>x.productId===productId&&x.variantId===variantId&&x.market===market());const origin=ui.productOrigin?.productId===productId&&ui.productOrigin.market===market()?ui.productOrigin:row.origin;if(origin)row.origin=origin;event('cart_added',{...origin,productId,variantId,market:market()});render();toast(L('已加入购物车。','Added to your bag.'));return true;}
function detailModal(id){ui.detailOpen=ui.productOrigin;const p=PRODUCTS.find(p=>p.id===id);if(!p)return;modal(esc(p.name),`<div class="detail-art">${productArt(p)}</div><div class="detail-price">${money(localPrice(p,market()),market())}<span>★ ${p.rating}</span></div><p>${esc(p.description)}</p><div class="specs">${p.specs.battery?`<div><span>${L('标称续航','Rated battery')}</span><strong>${p.specs.battery}h</strong></div>`:''}<div><span>${L('重量','Weight')}</span><strong>${p.specs.weight}g</strong></div><div><span>${L('演示配送','Demo delivery')}</span><strong>${p.days[market()]} ${L('天','days')}</strong></div>${[['capacity','容量','Capacity','mAh'],['powerW','功率','Power','W'],['volumeL','包袋容量','Bag volume','L'],['video','视频规格','Video',''],['brightnessLm','亮度','Brightness','lm']].filter(([k])=>p.specs[k]).map(([k,zh,en,u])=>`<div><span>${L(zh,en)}</span><strong>${esc(p.specs[k])}${u}</strong></div>`).join('')}<div><span>${L('库存','Stock')}</span><strong>${p.stock}</strong></div></div><p class="table-note">${esc(p.policy)}</p><div class="button-row"><button class="btn primary" data-choose-variant="${id}" ${!p.stock?'disabled':''}>${L('选择颜色','Choose color')}</button><button class="btn" data-ask-product="${id}">${ic('spark')}${L('问问助手','Ask about this')}</button></div>`);}
async function ask(text){if(ui.busy||!text.trim())return;const s=session();text=text.trim().slice(0,2000);s.messages.push({id:uid(),role:'user',text,market:market()});if(s.title==='新对话')s.title=text.slice(0,32);ui.query='';ui.busy=true;ui.view='assistant';history.replaceState(null,'','#assistant');render();let extracted=null;
 if(ui.provider==='llm'){try{const r=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,market:market()}),signal:AbortSignal.timeout(22000)});if(!r.ok)throw Error();extracted=(await r.json()).analysis;}catch{toast(L('模型暂不可用，已使用规则分析。','Using offline rules while the model is unavailable.'));}}
 const result=runShoppingTurn(text,s.context,PRODUCTS,{market:market(),language:state.language,extracted,strategy:state.strategy,weights:state.searchWeights});s.context=result.context;const searchId=uid();if(result.search){event('search_results',{searchId,market:market(),strategy:state.strategy,query:result.query.text,productIds:result.products.map(p=>p.id)});result.search={query:result.search.query,strategy:result.search.strategy,counts:result.search.counts,sort:result.search.sort,weights:state.searchWeights};}s.messages.push({id:searchId,role:'assistant',result,market:market(),strategy:state.strategy});s.messages=s.messages.slice(-40);ui.busy=false;event('shopping_turn',{kind:result.kind,tools:result.trace.map(x=>x.tool)});render();if(result.action?.type==='add_cart')add(result.action.productId,result.action.variantId);requestAnimationFrame(()=>$('#shopping-query')?.focus());}
async function action(k){switch(k){case'refresh-lab':render();break;case'export-strategy':file('ShopMate-search-strategy.json',JSON.stringify(exportStrategy(ui.lab),null,2));break;case'reset-weights':ui.lab.weights={...DEFAULT_WEIGHTS};render();break;case'apply-strategy':{state.strategy=ui.lab.strategy;state.searchWeights={...ui.lab.weights};const s=conversation(ui.lab.market);state.sessions.unshift(s);state.sessions=state.sessions.slice(0,12);state.currentId=s.id;save();await ask(ui.lab.text);break;}case'close-modal':closeModal();break;case'language':state.language=state.language==='zh'?'en':'zh';save();render();break;case'new-chat':{const s=conversation(market());state.sessions.unshift(s);state.sessions=state.sessions.slice(0,12);state.currentId=s.id;ui.query='';save();nav('assistant');break;}case'history':modal(L('历史对话','Conversation history'),state.sessions.map(s=>`<button class="history-row" data-session="${s.id}"><strong>${esc(s.title)}</strong><span>${s.market} · ${s.messages.filter(m=>m.role==='user').length} ${L('轮','turns')}</span></button>`).join(''));break;case'ask-compare':if(state.compare.length<2){toast(L('请先选择至少两款商品。','Select at least two products.'));return;}await ask(L('比较 ','Compare ')+state.compare.map(id=>PRODUCTS.find(p=>p.id===id).name).join(' vs '));break;case'checkout':ui.handoff=false;event('checkout_preview',{market:market(),items:cartItems().map(x=>({productId:x.productId,searchId:x.origin?.searchId}))});nav('checkout');break;case'export-handoff':{const d=checkoutDraft(state.cart,market());if(!d.ok){toast(L('请先检查购物车。','Please review your bag.'));return;}file('ShopMate-checkout-handoff.json',JSON.stringify({...d,createdAt:new Date().toISOString()},null,2));ui.handoff=true;event('checkout_handoff_exported',{market:market(),items:d.items.length});render();break;}case'export-events':file('ShopMate-events.json',JSON.stringify(state.events,null,2));break;case'download-guide':{const r=await fetch('project-brief.md');file('ShopMate-project-brief.md',await r.text(),'text/markdown');break;}}}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a[data-nav],.backdrop');if(!el||el.disabled)return;if(el.classList.contains('backdrop')&&e.target===el){closeModal();return;}if(el.dataset.labTab){ui.lab.tab=el.dataset.labTab;render();return;}if(el.dataset.labStrategy){ui.lab.strategy=el.dataset.labStrategy;render();return;}if(el.dataset.evalCase){const c=EVAL_CASES.find(x=>x.id===el.dataset.evalCase);ui.lab.snapshot=null;ui.lab.text=c.text;ui.lab.market=c.market;ui.lab.tab='pipeline';render();return;}if(el.dataset.inspectSearch){const msg=session().messages.find(x=>x.id===el.dataset.inspectSearch);ui.lab.text=msg.result.query.text;ui.lab.market=msg.market;ui.lab.snapshot={text:ui.lab.text,market:msg.market,query:msg.result.query,sort:msg.result.search.sort||'match'};ui.lab.strategy=msg.strategy||'match';ui.lab.weights={...(msg.result.search.weights||DEFAULT_WEIGHTS)};ui.lab.tab='pipeline';nav('strategy');return;}if(el.dataset.nav){e.preventDefault();closeModal();nav(el.dataset.nav);return;}if(el.dataset.action){await action(el.dataset.action);return;}if(el.dataset.product){trackProduct(el,el.dataset.product);detailModal(el.dataset.product);return;}if(el.dataset.chooseVariant){if(!el.closest('#overlay'))trackProduct(el,el.dataset.chooseVariant);if(ui.detailOpen){event('product_detail_closed',ui.detailOpen);ui.detailOpen=null;}variantModal(el.dataset.chooseVariant);return;}if(el.dataset.askProduct){closeModal();await ask(L('请介绍 ','Tell me about ')+PRODUCTS.find(p=>p.id===el.dataset.askProduct).name+L(' 的参数和详情。',' in detail.'));return;}if(el.dataset.compare){const id=el.dataset.compare;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else{toast(L('最多比较三款商品。','Compare up to three products.'));return;}save();render();return;}if(el.dataset.example!==undefined){const x=EXAMPLES[Number(el.dataset.example)];session().market=x.market;await ask(L(x.zh,x.en));return;}if(el.dataset.followup){await ask(el.dataset.followup);return;}if(el.dataset.category){ui.category=el.dataset.category;render();return;}if(el.dataset.session){state.currentId=el.dataset.session;ui.query='';save();closeModal();nav('assistant');return;}if(el.dataset.quantity){const x=state.cart.find(x=>x.id===el.dataset.quantity),delta=Number(el.dataset.delta);if(!x)return;if(delta>0){add(x.productId,x.variantId);return;}x.quantity--;state.cart=state.cart.filter(x=>x.quantity>0);event('cart_quantity_updated',{productId:x.productId});render();return;}if(el.dataset.removeCart){state.cart=state.cart.filter(x=>x.id!==el.dataset.removeCart);event('cart_removed',{});render();return;}});
document.addEventListener('submit',async e=>{if(!['chat-form','variant-form','strategy-form'].includes(e.target.id))return;e.preventDefault();if(e.target.id==='strategy-form'){ui.lab.text=$('#lab-query').value.trim();ui.lab.market=$('#lab-market').value;render();return;}if(e.target.id==='chat-form'){await ask($('#shopping-query').value);return;}const id=e.target.dataset.product,variant=new FormData(e.target).get('variant');if(add(id,variant))closeModal();});
document.addEventListener('change',e=>{if(e.target.id==='lab-strategy'){ui.lab.strategy=e.target.value;render();}if(e.target.id==='lab-market'){ui.lab.market=e.target.value;render();}if(e.target.dataset.labWeight){const key=e.target.dataset.labWeight;ui.lab.weights[key]=Number(e.target.value);render();document.querySelector('[data-lab-weight="'+key+'"]')?.focus();}if(e.target.id==='market'){session().market=e.target.value;session().context={};ui.handoff=false;save();render();toast(L('已切换购物市场，下一轮需求将重新识别。','Market changed; the next request starts a fresh brief.'));}if(e.target.id==='catalog-sort'){ui.sort=e.target.value;render();}if(e.target.id==='catalog-budget'){ui.price=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='lab-query')ui.lab.text=e.target.value;if(e.target.dataset.labWeight){$('#weight-value-'+e.target.dataset.labWeight).textContent=e.target.value;}if(e.target.id==='shopping-query')ui.query=e.target.value;if(e.target.id==='catalog-search'){const pos=e.target.selectionStart;ui.search=e.target.value;render();$('#catalog-search').focus();$('#catalog-search').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.target.id==='shopping-query'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit();}if(e.key==='Tab'&&$('#overlay .modal')){const els=[...$('#overlay .modal').querySelectorAll('button:not(:disabled),input,select,a')].filter(x=>x.offsetParent!==null),a=els[0],b=els.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus();}}});
function trackProduct(el,productId){const article=el.closest('[data-search-id]');ui.productOrigin=article?{searchId:article.dataset.searchId,productId,market:article.dataset.searchMarket,strategy:article.dataset.searchStrategy}:null;if(ui.productOrigin)event('product_clicked',ui.productOrigin);}
let impressionObserver;
function observeSearchCards(){impressionObserver?.disconnect();if(!('IntersectionObserver' in window))return;impressionObserver=new IntersectionObserver(entries=>{for(const x of entries){if(!x.isIntersecting||x.intersectionRatio<.5)continue;const card=x.target,article=card.closest('[data-search-id]'),detail={searchId:article.dataset.searchId,productId:card.dataset.productId,market:article.dataset.searchMarket,strategy:article.dataset.searchStrategy};if(!state.events.some(e=>e.type==='search_impression'&&e.detail.searchId===detail.searchId&&e.detail.productId===detail.productId))event('search_impression',detail);impressionObserver.unobserve(card);}},{threshold:.5});document.querySelectorAll('[data-search-id] .product-card').forEach(card=>impressionObserver.observe(card));}
document.addEventListener('toggle',e=>{if(e.target.matches?.('.weight-controls'))ui.lab.weightsOpen=e.target.open;},true);
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);ui.view=['assistant','catalog','compare','cart','checkout','guide','strategy'].includes(v)?v:'assistant';render();});
save();render();fetch('/api/health',{signal:AbortSignal.timeout(2000)}).then(r=>r.ok?r.json():null).then(d=>{ui.provider=d?.provider||'rules';}).catch(()=>{});
